    .sankey-header { margin-bottom: 24px; }
    .sankey-title { font-size: 1.25rem; font-weight: 600; color: var(--text); margin-bottom: 6px; }
    .sankey-subtitle { font-size: 0.875rem; color: var(--text-secondary); }

    .sankey-wrapper {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 32px;
      overflow-x: auto;
    }

