  </main>

  <!-- Tooltip -->
  <div id="sankeyTooltip" style="position:fixed;pointer-events:none;display:none;background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:10px 14px;font-size:13px;color:var(--text);box-shadow:0 4px 20px rgba(0,0,0,0.2);z-index:9000;max-width:240px;line-height:1.5;"></div>

  <script>
    // === MENU ===
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // === THEME ===
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // === SCROLL REVEAL ===
    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });

    // === NUMBER COUNTERS ===
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count), suffix = el.dataset.suffix || '';
        var start = performance.now(), duration = 1200;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1), eased = 1 - Math.pow(1 - p, 3);
          el.textContent = Math.round(target * eased).toLocaleString() + suffix;
          if (p < 1) requestAnimationFrame(tick);
        })(start);
      });
    }
    var counterEl = document.querySelector('[data-count]');
    if (counterEl) {
      var cObs = new IntersectionObserver(function(entries) {
        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
      }, { threshold: 0.3 });
      cObs.observe(counterEl);
    }

    // === DOWNLOAD PNG ===
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2 });
        var a = document.createElement('a'); a.href = url;
        a.download = 'global-energy-flow-2022.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }

    // === SANKEY DATA ===
    var nodes = [
      { id: 'oil', stage: 'primary', label: 'Oil' },
      { id: 'coal', stage: 'primary', label: 'Coal' },
      { id: 'natural_gas', stage: 'primary', label: 'Natural Gas' },
      { id: 'nuclear', stage: 'primary', label: 'Nuclear' },
      { id: 'hydro', stage: 'primary', label: 'Hydropower' },
      { id: 'wind', stage: 'primary', label: 'Wind' },
      { id: 'solar', stage: 'primary', label: 'Solar' },
      { id: 'biomass', stage: 'primary', label: 'Biomass' },
      { id: 'geothermal', stage: 'primary', label: 'Geothermal' },
      { id: 'thermal_power', stage: 'transformation', label: 'Thermal Power' },
      { id: 'refining', stage: 'transformation', label: 'Refining & Petrochem' },
      { id: 'direct_use', stage: 'transformation', label: 'Direct Use' },
      { id: 'electricity_grid', stage: 'transformation', label: 'Electricity Grid' },
      { id: 'transport', stage: 'end_use', label: 'Transport' },
      { id: 'industry', stage: 'end_use', label: 'Industry' },
      { id: 'buildings', stage: 'end_use', label: 'Buildings' },
      { id: 'agriculture', stage: 'end_use', label: 'Agriculture' },
      { id: 'other', stage: 'end_use', label: 'Other' },
      { id: 'waste_heat', stage: 'end_use', label: 'Waste / Rejected Heat' }
    ];

    var flows = [
      { source: 'coal', target: 'thermal_power', value: 96.5 },
      { source: 'natural_gas', target: 'thermal_power', value: 42.8 },
      { source: 'oil', target: 'thermal_power', value: 8.2 },
      { source: 'nuclear', target: 'thermal_power', value: 29.4 },
      { source: 'oil', target: 'refining', value: 162.3 },
      { source: 'natural_gas', target: 'refining', value: 18.5 },
      { source: 'natural_gas', target: 'direct_use', value: 80.2 },
      { source: 'coal', target: 'direct_use', value: 60.8 },
      { source: 'biomass', target: 'direct_use', value: 42.6 },
      { source: 'hydro', target: 'electricity_grid', value: 15.8 },
      { source: 'wind', target: 'electricity_grid', value: 8.4 },
      { source: 'solar', target: 'electricity_grid', value: 5.9 },
      { source: 'geothermal', target: 'electricity_grid', value: 1.0 },
      { source: 'thermal_power', target: 'electricity_grid', value: 68.2 },
      { source: 'thermal_power', target: 'waste_heat', value: 108.7 },
      { source: 'refining', target: 'transport', value: 118.6 },
      { source: 'refining', target: 'industry', value: 35.4 },
      { source: 'refining', target: 'waste_heat', value: 26.8 },
      { source: 'electricity_grid', target: 'buildings', value: 38.2 },
      { source: 'electricity_grid', target: 'industry', value: 36.8 },
      { source: 'electricity_grid', target: 'transport', value: 4.1 },
      { source: 'electricity_grid', target: 'agriculture', value: 7.6 },
      { source: 'electricity_grid', target: 'other', value: 12.6 },
      { source: 'direct_use', target: 'industry', value: 82.4 },
      { source: 'direct_use', target: 'buildings', value: 56.7 },
      { source: 'direct_use', target: 'agriculture', value: 12.3 },
      { source: 'direct_use', target: 'waste_heat', value: 32.2 }
    ];

    // === NODE COLORS ===
    var nodeColors = {
      // Fossil fuels - warm grays/browns
      oil: '#78716c',
      coal: '#57534e',
      natural_gas: '#a8a29e',
      // Nuclear - purple
      nuclear: '#a78bfa',
      // Renewables - greens/teals
      hydro: '#06b6d4',
      wind: '#22d3ee',
      solar: '#fbbf24',
      biomass: '#84cc16',
      geothermal: '#f472b6',
      // Transformation - blues
      thermal_power: '#6b7280',
      refining: '#9ca3af',
      direct_use: '#60a5fa',
      electricity_grid: '#3b82f6',
      // End use - varied
      transport: '#8b5cf6',
      industry: '#ec4899',
      buildings: '#14b8a6',
      agriculture: '#a3e635',
      other: '#94a3b8',
      // WASTE HEAT - distinct warm orange (highlight)
      waste_heat: '#f97316'
    };

    // === SANKEY LAYOUT COMPUTATION ===
    function computeSankey() {
      var stageOrder = ['primary', 'transformation', 'end_use'];
      var nodeMap = {};
      nodes.forEach(function(n) { nodeMap[n.id] = Object.assign({}, n, { inflow: 0, outflow: 0 }); });

      flows.forEach(function(f) {
        nodeMap[f.source].outflow += f.value;
        nodeMap[f.target].inflow += f.value;
      });

      // Compute node sizes based on total flow
      nodes.forEach(function(n) {
        var nd = nodeMap[n.id];
        nd.total = Math.max(nd.inflow, nd.outflow);
      });

      return nodeMap;
    }

    function buildSankey() {
      var svg = d3.select('#sankeyChart');
      svg.selectAll('*').remove();

      var isDark = document.documentElement.classList.contains('theme-dark');
      var textColor = isDark ? '#EDEDED' : '#0f172a';
      var textSecondary = isDark ? '#888' : '#64748b';
      var bgColor = isDark ? '#141414' : '#FFFFFF';

      var container = document.querySelector('.sankey-wrapper');
      var totalW = Math.max(container ? container.clientWidth - 64 : 1200, 800);
      var totalH = Math.max(Math.round(totalW * 0.55), 520);

      svg.attr('width', totalW).attr('height', totalH);

      var marginL = 130, marginR = 160, marginT = 20, marginB = 30;
      var chartW = totalW - marginL - marginR;
      var chartH = totalH - marginT - marginB;

      var g = svg.append('g').attr('transform', 'translate(' + marginL + ',' + marginT + ')');

      // Stage x positions
      var stageX = { primary: 0, transformation: chartW * 0.42, end_use: chartW };
      var nodeW = 18;

      // Group nodes by stage
      var byStage = { primary: [], transformation: [], end_use: [] };
      nodes.forEach(function(n) { byStage[n.stage].push(n.id); });

      var nodeMap = computeSankey();

      // Compute vertical layout per stage
      var padding = 8;
      function layoutStage(stage) {
        var ids = byStage[stage];
        var totalFlow = d3.sum(ids, function(id) { return nodeMap[id].total; });
        var availH = chartH - padding * (ids.length - 1);
        var y = 0;
        ids.forEach(function(id) {
          var nd = nodeMap[id];
          nd.h = Math.max((nd.total / totalFlow) * availH, 4);
          nd.y = y;
          nd.x = stageX[stage];
          y += nd.h + padding;
        });
        // Center the column
        var totalUsed = y - padding;
        var offset = (chartH - totalUsed) / 2;
        if (offset > 0) {
          ids.forEach(function(id) { nodeMap[id].y += offset; });
        }
      }

      layoutStage('primary');
      layoutStage('transformation');
      layoutStage('end_use');

      // Track flow offsets for ribbons
      var sourceOffsets = {}, targetOffsets = {};
      nodes.forEach(function(n) { sourceOffsets[n.id] = 0; targetOffsets[n.id] = 0; });

      // Draw flows (links)
      var tooltip = document.getElementById('sankeyTooltip');

      // Sort flows to draw waste_heat last (on top for highlight)
      var sortedFlows = flows.slice().sort(function(a, b) {
        if (a.target === 'waste_heat' && b.target !== 'waste_heat') return 1;
        if (b.target === 'waste_heat' && a.target !== 'waste_heat') return -1;
        return b.value - a.value;
      });

      sortedFlows.forEach(function(f) {
        var src = nodeMap[f.source];
        var tgt = nodeMap[f.target];
        if (!src || !tgt) return;

        var srcTotalFlow = d3.sum(flows.filter(function(fl) { return fl.source === f.source; }), function(fl) { return fl.value; });
        var tgtTotalFlow = d3.sum(flows.filter(function(fl) { return fl.target === f.target; }), function(fl) { return fl.value; });

        var srcBandH = (f.value / srcTotalFlow) * src.h;
        var tgtBandH = (f.value / tgtTotalFlow) * tgt.h;

        var sy0 = src.y + sourceOffsets[f.source];
        var sy1 = sy0 + srcBandH;
        var ty0 = tgt.y + targetOffsets[f.target];
        var ty1 = ty0 + tgtBandH;

        sourceOffsets[f.source] += srcBandH;
        targetOffsets[f.target] += tgtBandH;

        var sx = src.x + nodeW;
        var tx = tgt.x;
        var cpX = (sx + tx) / 2;

        var pathD = 'M ' + sx + ' ' + sy0 +
          ' C ' + cpX + ' ' + sy0 + ', ' + cpX + ' ' + ty0 + ', ' + tx + ' ' + ty0 +
          ' L ' + tx + ' ' + ty1 +
          ' C ' + cpX + ' ' + ty1 + ', ' + cpX + ' ' + sy1 + ', ' + sx + ' ' + sy1 +
          ' Z';

        var isWaste = f.target === 'waste_heat';
        var isFossil = ['oil','coal','natural_gas'].includes(f.source);
        var baseColor = isWaste ? '#f97316' : nodeColors[f.source] || '#888';
        var opacity = isWaste ? 0.72 : (isFossil ? 0.38 : 0.3);

        g.append('path')
          .attr('d', pathD)
          .attr('fill', baseColor)
          .attr('opacity', opacity)
          .style('cursor', 'pointer')
          .on('mouseover', function(event) {
            d3.select(this).attr('opacity', Math.min(opacity + 0.3, 0.92));
            tooltip.style.display = 'block';
            tooltip.innerHTML = '<strong>' + nodeMap[f.source].label + '</strong> → <strong>' + nodeMap[f.target].label + '</strong><br>' +
              '<span style="color:var(--text-secondary)">Flow: </span><strong>' + f.value.toFixed(1) + ' EJ</strong>' +
              (isWaste ? '<br><span style="color:#f97316;font-size:11px;">⚠ Rejected heat / loss</span>' : '');
          })
          .on('mousemove', function(event) {
            var x = event.clientX + 14, y = event.clientY - 10;
            if (x + 240 > window.innerWidth) x = event.clientX - 254;
            tooltip.style.left = x + 'px';
            tooltip.style.top = y + 'px';
          })
          .on('mouseout', function() {
            d3.select(this).attr('opacity', opacity);
            tooltip.style.display = 'none';
          });
      });

      // Draw nodes (rectangles)
      nodes.forEach(function(n) {
        var nd = nodeMap[n.id];
        if (!nd) return;
        var isWaste = n.id === 'waste_heat';
        var color = nodeColors[n.id] || '#888';

        g.append('rect')
          .attr('x', nd.x)
          .attr('y', nd.y)
          .attr('width', nodeW)
          .attr('height', nd.h)
          .attr('fill', color)
          .attr('rx', 3)
          .style('cursor', 'pointer')
          .on('mouseover', function(event) {
            tooltip.style.display = 'block';
            var inVal = nd.inflow > 0 ? nd.inflow.toFixed(1) : null;
            var outVal = nd.outflow > 0 ? nd.outflow.toFixed(1) : null;
            tooltip.innerHTML = '<strong>' + nd.label + '</strong><br>' +
              (inVal ? '<span style="color:var(--text-secondary)">In: </span><strong>' + inVal + ' EJ</strong><br>' : '') +
              (outVal ? '<span style="color:var(--text-secondary)">Out: </span><strong>' + outVal + ' EJ</strong>' : '');
          })
          .on('mousemove', function(event) {
            var x = event.clientX + 14, y = event.clientY - 10;
            if (x + 240 > window.innerWidth) x = event.clientX - 254;
            tooltip.style.left = x + 'px';
            tooltip.style.top = y + 'px';
          })
          .on('mouseout', function() { tooltip.style.display = 'none'; });

        // Labels
        var labelSide = nd.stage === 'primary' ? 'left' : (nd.stage === 'end_use' ? 'right' : 'right');
        var labelX, anchor;
        if (nd.stage === 'primary') {
          labelX = nd.x - 8; anchor = 'end';
        } else if (nd.stage === 'end_use') {
          labelX = nd.x + nodeW + 8; anchor = 'start';
        } else {
          labelX = nd.x + nodeW + 6; anchor = 'start';
        }

        var labelY = nd.y + nd.h / 2;
        var fontSize = Math.min(Math.max(nd.h * 0.38, 9), 12);

        g.append('text')
          .attr('x', labelX)
          .attr('y', labelY)
          .attr('dy', '0.35em')
          .attr('text-anchor', anchor)
          .attr('font-size', fontSize + 'px')
          .attr('font-family', 'Inter, sans-serif')
          .attr('font-weight', isWaste ? 600 : 400)
          .attr('fill', isWaste ? '#f97316' : textColor)
          .text(nd.label);

        // Value label if node is large enough
        if (nd.h > 22) {
          var valText = nd.total.toFixed(0) + ' EJ';
          g.append('text')
            .attr('x', labelX)
            .attr('y', labelY + fontSize * 1.1)
            .attr('dy', '0.35em')
            .attr('text-anchor', anchor)
            .attr('font-size', Math.min(fontSize - 1, 10) + 'px')
            .attr('font-family', 'Inter, sans-serif')
            .attr('fill', textSecondary)
            .text(valText);
        }
      });

